function helpers(g){return {
line(x,y,a,b,c,w=1){g.beginPath();g.moveTo(x,y);g.lineTo(a,b);g.strokeStyle=c;g.lineWidth=w;g.lineCap='round';g.stroke();},
ellipse(x,y,a,b,c){g.beginPath();g.ellipse(x,y,a,b,0,0,Math.PI*2);g.fillStyle=c;g.fill();},
rect(x,y,w,h,r,c){g.beginPath();g.roundRect(x,y,w,h,r);g.fillStyle=c;g.fill();},
poly(p,c,st,w=1){g.beginPath();p.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();if(c){g.fillStyle=c;g.fill();}if(st){g.strokeStyle=st;g.lineWidth=w;g.stroke();}}
};}
function artLayer(g,image,b){if(!image)return;g.save();g.beginPath();g.rect(b.x,b.y,b.width,b.height);g.clip();g.drawImage(image,0,0);g.restore();}
