function createDefaultRail(frame,backdrop){
 const band=document.createElement('div'),group=document.createElement('img');
 band.className='matte-attribution-rail';band.hidden=true;
 group.alt='Cerebras · Kimi 3.1 Pro · dheerajshah.com';group.width=1509;group.height=102;
 group.decoding='async';
 const repeats=['left','right'].map(side=>{
  const copy=group.cloneNode();copy.className='rail-repeat-'+side;copy.alt='';return copy;
 });
 band.append(group,...repeats);frame.insertBefore(band,backdrop);
 let requested=false;
 return visible=>{
  band.hidden=!visible;
  if(visible&&!requested){requested=true;for(const image of [group,...repeats])image.src=railGroupSrc;}
 };
}
