  ctx.beginPath=function(){points=[];return native.begin.call(this);};
  ctx.moveTo=function(x,y){record(x,y);return native.move.call(this,x,y);};
  ctx.lineTo=function(x,y){record(x,y);return native.line.call(this,x,y);};
